[
  {
    "title": "countdown-competes-with-reading",
    "claim": "Image #2 presents strategy and control instructions alongside “STARTING IN 7,” without a visible option to defer the start.",
    "reason": "A new player is being asked to understand the controls while the screen communicates a deadline.",
    "suggest": "Keep the introduction open until the player selects Fight; reserve countdowns for an explicitly confirmed start."
  },
  {
    "title": "stick-meanings-separated",
    "claim": "Image #3 places direction meanings in a separate strip above chevron-only stick sectors, while image #15 shows those sectors without the explanatory strip.",
    "reason": "The player must look elsewhere—or remember the mapping—to identify what each thumb direction means.",
    "suggest": "Put persistent action labels directly around the corresponding stick sectors, replacing the chevrons and reflowing the controls rather than shrinking the labels."
  },
  {
    "title": "reference-name-mismatch",
    "claim": "The reference button reads “MOVES” in image #3, but its displayed reference sheet is titled “TECHNIQUES” in image #6.",
    "reason": "Different names for the same reference add avoidable terminology to an already unfamiliar control system.",
    "suggest": "Rename the button “Techniques” to match the sheet and the technique stick."
  },
  {
    "title": "opening-example-missing",
    "claim": "Image #2 explains the input combination abstractly without a named example, whereas image #6 explicitly pairs Lunge Punch with centered stance and forward technique.",
    "reason": "One immediately usable move gives a beginner a clearer starting point than the combination rule alone.",
    "suggest": "Add “Try Lunge Punch: stance centered + technique forward” to the introduction, using the same labeled input notation as the reference sheet."
  },
  {
    "title": "text-size-unverified",
    "claim": "The HUD names and stick captions in image #3 are visibly smaller than the settings labels in image #7, but these raster frames cannot establish their CSS font sizes.",
    "reason": "Visual comparison alone cannot verify compliance with the required 18 CSS px minimum.",
    "suggest": "Measure computed font sizes at 390×844 and desktop for HUD names, timer suffixes, stick captions, countdowns, and technique metadata; raise any below 18px and adjust layout instead of scaling text."
  }
]
